//! End-to-end conversion test with a real (hand-crafted, minimal) PDF.
//!
//! The fixture `tests/fixtures/hello.pdf` is generated by the project (a
//! one-page Helvetica PDF), so no third-party binary is committed.

use std::path::PathBuf;

use pdf2md_gui::convert::{ConvertOptions, run_conversion};

fn fixture(name: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("fixtures")
        .join(name)
}

#[test]
fn text_pdf_converts_to_markdown() {
    let result = run_conversion(&fixture("hello.pdf"), &ConvertOptions::default())
        .expect("fixture PDF should convert");
    assert_eq!(result.pdf_type, pdf_inspector::PdfType::TextBased);
    let markdown = result.markdown.expect("text PDF should yield markdown");
    assert!(
        markdown.contains("Hello PDF Inspector"),
        "unexpected markdown: {markdown:?}"
    );
}

#[test]
fn page_filter_limits_conversion() {
    let opts = ConvertOptions {
        page_spec: "1".to_string(),
        ..ConvertOptions::default()
    };
    let result = run_conversion(&fixture("hello.pdf"), &opts).expect("page filter should work");
    assert!(result.markdown.is_some());
}

#[test]
fn invalid_page_spec_is_rejected_before_touching_the_pdf() {
    let opts = ConvertOptions {
        page_spec: "0".to_string(),
        ..ConvertOptions::default()
    };
    assert!(run_conversion(&fixture("hello.pdf"), &opts).is_err());
}
